+import {
+  clientStatusLabel,
+} from "@/features/board/lib/status";
+import { getStatusStyle } from "@/features/tasks/lib/status";
+
+const ACTIVE_STATUSES = new Set(["in_progress", "reviewing"]);
+
+function StatusSpinner({ className }: { className?: string }) {
+  return (
+    <svg
+      className={["status-spinner", className].filter(Boolean).join(" ")}
